<?php
session_start();
$dbFile = __DIR__ . '/data/votesecure.sqlite';
if (!is_dir(__DIR__ . '/data')) mkdir(__DIR__ . '/data', 0777, true);
$db = new PDO('sqlite:' . $dbFile);
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
$db->exec("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, is_admin INTEGER DEFAULT 0, otp TEXT, otp_verified INTEGER DEFAULT 0)");
$db->exec("CREATE TABLE IF NOT EXISTS candidates (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, party TEXT NOT NULL)");
$db->exec("CREATE TABLE IF NOT EXISTS votes (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER UNIQUE NOT NULL, candidate_id INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)");
if ((int)$db->query('SELECT COUNT(*) FROM candidates')->fetchColumn() === 0) {
  $s=$db->prepare('INSERT INTO candidates(name,party) VALUES(?,?)');
  foreach ([['Aarav Sharma','Progress Alliance'],['Diya Patel','People First'],['Kabir Mehta','Future Front']] as $c) $s->execute($c);
}
$adminEmail='admin@voting.local';
$check=$db->prepare('SELECT id FROM users WHERE email=?'); $check->execute([$adminEmail]);
if (!$check->fetch()) { $s=$db->prepare('INSERT INTO users(name,email,password,is_admin,otp_verified) VALUES(?,?,?,?,1)'); $s->execute(['Administrator',$adminEmail,password_hash('Admin@12345',PASSWORD_DEFAULT),1]); }
function h($v){return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');}
function go($m='home'){header('Location: ?page='.$m);exit;}
$page=$_GET['page'] ?? 'home'; $error=''; $notice='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $action=$_POST['action'] ?? '';
 if ($action==='register') {
  $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $pw=$_POST['password']??'';
  if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pw)<6) $error='Enter your name, a valid email, and a password of at least 6 characters.';
  else { try { $otp=(string)random_int(100000,999999); $s=$db->prepare('INSERT INTO users(name,email,password,otp,otp_verified) VALUES(?,?,?,?,0)'); $s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$otp]); $_SESSION['pending_user']=(int)$db->lastInsertId(); $_SESSION['demo_otp']=$otp; go('verify'); } catch(Throwable $e){$error='That email is already registered.';} }
  $page='register';
 } elseif ($action==='verify') {
  $id=$_SESSION['pending_user']??0; $otp=trim($_POST['otp']??''); $s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch(PDO::FETCH_ASSOC);
  if($u && hash_equals((string)$u['otp'],$otp)){ $db->prepare('UPDATE users SET otp_verified=1,otp=NULL WHERE id=?')->execute([$id]);$_SESSION['user_id']=$id;unset($_SESSION['pending_user'],$_SESSION['demo_otp']);go('dashboard'); } else {$error='Incorrect OTP. Use the demo OTP shown below.';$page='verify';}
 } elseif ($action==='login') {
  $s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch(PDO::FETCH_ASSOC);
  if($u && password_verify($_POST['password']??'',$u['password'])) { if((int)$u['is_admin']===1){$_SESSION['user_id']=$u['id'];go('admin');} $otp=(string)random_int(100000,999999);$db->prepare('UPDATE users SET otp=?,otp_verified=0 WHERE id=?')->execute([$otp,$u['id']]);$_SESSION['pending_user']=$u['id'];$_SESSION['demo_otp']=$otp;go('verify'); } else {$error='Invalid email or password.';$page='login';}
 } elseif ($action==='vote') {
  $uid=$_SESSION['user_id']??0; $cid=(int)($_POST['candidate_id']??0); $s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$u=$s->fetch(PDO::FETCH_ASSOC);
  if(!$u || (int)$u['is_admin']===1) {$error='Please log in as a voter.';$page='login';}
  else { try{$s=$db->prepare('INSERT INTO votes(user_id,candidate_id) VALUES(?,?)');$s->execute([$uid,$cid]);go('results');}catch(Throwable $e){$error='You have already voted, or the selected candidate is invalid.';$page='dashboard';} }
 }
}
$uid=$_SESSION['user_id']??0;$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$current=$s->fetch(PDO::FETCH_ASSOC) ?: null;
if ($page==='logout') {session_destroy();go('home');}
if ($page==='admin' && (!$current || !(int)$current['is_admin'])) go('login');
if ($page==='dashboard' && !$current) go('login');
function headerHtml($title){echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' | VoteSecure</title><style>
:root{--navy:#101b35;--blue:#3659d9;--pale:#f2f5ff;--ink:#18223b;--muted:#69738c}*{box-sizing:border-box}body{margin:0;background:#f5f7fc;color:var(--ink);font:16px/1.5 Arial,sans-serif}.nav{background:var(--navy);color:white;padding:18px max(calc((100% - 1050px)/2),22px);display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:22px;font-weight:800;letter-spacing:.2px}.nav a{color:white;text-decoration:none;margin-left:16px}.wrap{max-width:1000px;margin:38px auto;padding:0 20px}.hero{background:linear-gradient(120deg,#101b35,#3659d9);color:white;padding:36px;border-radius:20px}.hero h1{font-size:clamp(28px,5vw,44px);line-height:1.1;margin:8px 0 14px}.muted{color:var(--muted)}.hero p{max-width:650px;color:#e0e7ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:20px}.card{background:white;border:1px solid #e4e8f2;border-radius:15px;padding:22px;box-shadow:0 5px 20px #18264a0a}.btn{display:inline-block;background:var(--blue);color:white;border:0;border-radius:9px;padding:11px 16px;text-decoration:none;font-weight:700;cursor:pointer}.btn.secondary{background:#e9edff;color:#233a9b}.btn.danger{background:#9c2638}.field{margin:14px 0}.field label{display:block;font-weight:700;margin-bottom:6px}.field input,.field select{width:100%;padding:12px;border:1px solid #cdd4e4;border-radius:9px;font-size:16px}.alert{padding:12px 15px;border-radius:10px;margin:15px 0;background:#ffeded;color:#8c1c2d}.success{background:#e6f8ef;color:#17633d}.otp{font-size:28px;letter-spacing:5px;font-weight:800;color:#233a9b;background:#edf1ff;padding:12px;border-radius:9px;text-align:center}.candidate{display:flex;justify-content:space-between;align-items:center;gap:12px}.bar{height:9px;background:#e8ecf7;border-radius:20px;overflow:hidden;margin:8px 0}.bar span{display:block;height:100%;background:var(--blue)}footer{text-align:center;color:var(--muted);padding:25px}@media(max-width:600px){.nav{padding:16px;align-items:flex-start}.nav a{margin-left:8px}.hero{padding:25px}.wrap{margin:22px auto}}
</style></head><body><div class="nav"><div class="brand">🗳️ VoteSecure</div><div><a href="?page=home">Home</a><a href="?page=results">Results</a>'.(isset($_SESSION['user_id'])?'<a href="?page=dashboard">Dashboard</a><a href="?page=logout">Logout</a>':'<a href="?page=login">Login</a><a href="?page=register">Register</a>').'</div></div><main class="wrap">';}
function footerHtml(){echo '</main><footer>VoteSecure · Educational project demo · One vote per account</footer></body></html>';}
headerHtml(ucfirst($page)); if($error)echo '<div class="alert">'.h($error).'</div>'; if($notice)echo '<div class="alert success">'.h($notice).'</div>';
switch($page){
case 'home': echo '<section class="hero"><div>SECURE • SIMPLE • TRANSPARENT</div><h1>Your vote.<br> Your voice.</h1><p>A student-friendly online voting system with account verification, one-vote protection, and live results.</p><a class="btn" href="?page=register">Get started</a> <a class="btn secondary" href="?page=results">View results</a></section><div class="grid"><div class="card"><h3>🔐 OTP verification</h3><p class="muted">Demo OTP confirms login without an external SMS service.</p></div><div class="card"><h3>☑️ One account, one vote</h3><p class="muted">The database prevents an account from voting more than once.</p></div><div class="card"><h3>📊 Live results</h3><p class="muted">See vote counts update after ballots are submitted.</p></div></div><p class="muted">Demo admin: <b>admin@voting.local</b> / <b>Admin@12345</b></p>';break;
case 'register': echo '<div class="card" style="max-width:520px;margin:auto"><h1>Create voter account</h1><form method="post"><input type="hidden" name="action" value="register"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password (minimum 6 characters)</label><input type="password" name="password" minlength="6" required></div><button class="btn">Register and get OTP</button></form></div>';break;
case 'login': echo '<div class="card" style="max-width:520px;margin:auto"><h1>Login</h1><form method="post"><input type="hidden" name="action" value="login"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form><p class="muted">Voters verify with an OTP after entering their password.</p></div>';break;
case 'verify': echo '<div class="card" style="max-width:520px;margin:auto"><h1>Verify with OTP</h1><p>Enter the six-digit demo OTP to complete verification.</p><p class="muted">Your demo OTP:</p><div class="otp">'.h($_SESSION['demo_otp']??'------').'</div><form method="post"><input type="hidden" name="action" value="verify"><div class="field"><label>6-digit OTP</label><input name="otp" inputmode="numeric" maxlength="6" required></div><button class="btn">Verify and continue</button></form><p class="muted">For this local demo, no SMS service is required.</p></div>';break;
case 'dashboard': $s=$db->prepare('SELECT id FROM votes WHERE user_id=?');$s->execute([$current['id']]);$hasVoted=(bool)$s->fetchColumn(); echo '<h1>Welcome, '.h($current['name']).'</h1><p class="muted">Your voter dashboard</p>';if($hasVoted)echo '<div class="card"><h2>Vote recorded</h2><p>You have already submitted your vote. Thanks for participating.</p><a class="btn" href="?page=results">View results</a></div>';else {echo '<div class="card"><h2>Cast your vote</h2><p>Choose one candidate. Your choice cannot be changed after submission.</p><form method="post"><input type="hidden" name="action" value="vote">';foreach($db->query('SELECT * FROM candidates') as $c)echo '<div class="field"><label><input type="radio" name="candidate_id" value="'.(int)$c['id'].'" required> '.h($c['name']).' <span class="muted">— '.h($c['party']).'</span></label></div>';echo '<button class="btn">Submit vote</button></form></div>';}break;
case 'results': $rows=$db->query('SELECT c.id,c.name,c.party,COUNT(v.id) votes FROM candidates c LEFT JOIN votes v ON v.candidate_id=c.id GROUP BY c.id ORDER BY votes DESC,c.name')->fetchAll(PDO::FETCH_ASSOC);$total=(int)$db->query('SELECT COUNT(*) FROM votes')->fetchColumn();echo '<h1>Election results</h1><p class="muted">Total votes cast: '. $total .'</p><div class="grid">';foreach($rows as $r){$pct=$total?round($r['votes']/$total*100):0;echo '<div class="card"><h2>'.h($r['name']).'</h2><p class="muted">'.h($r['party']).'</p><div style="font-size:28px;font-weight:800">'.(int)$r['votes'].' <small style="font-size:14px">votes</small></div><div class="bar"><span style="width:'.$pct.'%"></span></div><p class="muted">'.$pct.'% of votes</p></div>'; }echo '</div><p><a class="btn secondary" href="?page=home">Back home</a></p>';break;
case 'admin': $rows=$db->query('SELECT c.name,c.party,COUNT(v.id) votes FROM candidates c LEFT JOIN votes v ON v.candidate_id=c.id GROUP BY c.id ORDER BY votes DESC')->fetchAll(PDO::FETCH_ASSOC);echo '<h1>Admin dashboard</h1><div class="card"><p>Signed in as administrator.</p><h2>Election summary</h2><p>Registered users: '.(int)$db->query('SELECT COUNT(*) FROM users WHERE is_admin=0')->fetchColumn().'</p><p>Total votes: '.(int)$db->query('SELECT COUNT(*) FROM votes')->fetchColumn().'</p><a class="btn" href="?page=results">Open public results</a></div><div class="card"><h2>Candidate totals</h2>';foreach($rows as $r)echo '<p><b>'.h($r['name']).'</b> — '.h($r['party']).': '.(int)$r['votes'].' votes</p>';echo '</div><p class="muted">This lightweight version is intended for classroom demonstration, not a real public election.</p>';break;
default: echo '<div class="card"><h1>Page not found</h1><a class="btn" href="?page=home">Return home</a></div>';
}
footerHtml();
